/*!50003 DROP PROCEDURE IF EXISTS  `Pr_Agenda` */;

DELIMITER $$

/*!50003 CREATE  PROCEDURE `Pr_Agenda`(IN `pEmpresa` INT, IN `pSala` INT, IN `pAnio` INT, IN `pMes` INT)
BEGIN
   /*DECLARACION DE VARIABLES*/
   DECLARE vSalaId INT DEFAULT 0;
   DECLARE vMaximoRegistros, vMinutosPorRegistro, vDia INT;
   DECLARE vHoraInicio, vEstado CHAR(50);
   DECLARE SALIDA BOOLEAN;
   DECLARE ACCION INT DEFAULT 0;
   DECLARE done BOOLEAN DEFAULT 0;
   DECLARE vFecha, vFechaInicial, vFechaFinal DATE;
   DECLARE vHora, vHoraFinal DATETIME;
   DECLARE vUltimoRegistro INT DEFAULT 0;
   DECLARE vTextoAlmuerzo varchar(100) DEFAULT 'HORA DE ALMUERZO';
   
   /*CURSOR DE SALAS POR EMPRESA*/
   DECLARE CurSalas CURSOR FOR SELECT id, maximo_registros, minutos_por_registro, left(hora_inicio, 5), estado FROM salas WHERE empresa_id = pEmpresa ORDER BY 1;
   
   DECLARE CONTINUE HANDLER FOR SQLSTATE '20000' SET ACCION = 1;
   
   SET vFechaInicial := STR_TO_DATE(CONCAT(pAnio,'-',LPAD(pMes,2,'0'),'-01'),'%Y-%m-%d');
   SET vFechaFinal   := LAST_DAY(vFechaInicial);
   SET vFecha        := vFechaInicial;
   
   OPEN CurSalas;
   Salas: REPEAT
      FETCH CurSalas INTO vSalaId, vMaximoRegistros, vMinutosPorRegistro, vHoraInicio, vEstado;
      SELECT vSalaId, vMaximoRegistros, vMinutosPorRegistro, vHoraInicio, vEstado;
      SET vFecha := vFechaInicial;
      fechasLabel: WHILE vFecha <= vFechaFinal DO
	     SET vHora = STR_TO_DATE(CONCAT(vFecha,' ',vHoraInicio), '%Y-%m-%d %H:%i');
         SET vHoraFinal = date_add(vHora, interval vMinutosPorRegistro minute);
         SET vUltimoRegistro = 1;
         horaLabel: WHILE vUltimoRegistro <= vMaximoREgistros DO
            if vHora like '%13:00%' then
				VALUES(pEmpresa, vSalaId, vHora, vHoraFinal, 'B', now(), 1, vTextoAlmuerzo, now(), 0, now(), 0);
            elseif vHora like '%13:30%' then
				VALUES(pEmpresa, vSalaId, vHora, vHoraFinal, 'B', now(), 1, vTextoAlmuerzo, now(), 0, now(), 0);
            else
				VALUES(pEmpresa, vSalaId, vHora, vHoraFinal, 'P', now(), 0, now(), 0);
            end if;
            SET vHora = DATE_ADD(vHora, INTERVAL vMinutosPorRegistro MINUTE);
            SET vHoraFinal = date_add(vHora, interval vMinutosPorRegistro minute);
            SET vUltimoRegistro = vUltimoRegistro + 1;
         END WHILE horaLabel;
         SET vFecha := DATE_ADD(vFecha, INTERVAL 1 DAY);
      END WHILE fechasLabel;
   UNTIL SALIDA END REPEAT Salas;
   CLOSE CurSalas;
END */$$
DELIMITER ;

/* Procedure structure for procedure `Pr_LlenarAnioAgenda` */

/*!50003 DROP PROCEDURE IF EXISTS  `Pr_LlenarAnioAgenda` */;

DELIMITER $$

/*!50003 CREATE  PROCEDURE `Pr_LlenarAnioAgenda`(`pEmpresa` INTEGER, `pFechaInicio` DATE, `pFechaFin` DATE)
BEGIN
   DECLARE i                  INTEGER    DEFAULT 1;
   DECLARE salaId             INTEGER;
   DECLARE maximoRegistros    INTEGER;
   DECLARE minutosPorRegistro INTEGER;
   DECLARE horaInicio         INTEGER;
   DECLARE minutosInicio      INTEGER;
   DECLARE estado             VARCHAR(2) DEFAULT 'I';
   DECLARE finDeCiclo         INTEGER    DEFAULT 0;
   DECLARE fechaInicio, fechaFin, fechaActual, fechaInicial, fechaFinal  DATETIME DEFAULT DATE_FORMAT(CONCAT(pFechaInicio,' 08:00'), '%Y-%m-%d %H:%i');
   DECLARE dia INTEGER DEFAULT 86400;
      
   DECLARE crSalas CURSOR FOR SELECT s.id, s.maximo_registros, s.minutos_por_registro, SUBSTRING(s.hora_inicio, 1, 2) as hora_inicio, SUBSTRING(s.hora_inicio, 4, 2) as minutos_inicio, s.estado
                                FROM granai_db.salas as s
                                WHERE s.empresa_id = pEmpresa
                                  /*and s.id = 1*/
		                        ORDER BY 1;
   DECLARE CONTINUE HANDLER FOR NOT FOUND SET finDeCiclo = 1;

   SET fechaInicio = pFechaInicio;
   SET fechaFin    = pFechaFin;
   SET fechaActual = pFechaInicio;
   
   OPEN crSalas;
   ciclo: LOOP
      FETCH crSalas INTO salaId, maximoRegistros, minutosPorRegistro, horaInicio, minutosInicio, estado;
      WHILE fechaActual <= fechaFin DO
		 SET finDeCiclo = 0;
         SET fechaActual = date_add(fechaActual, INTERVAL horaInicio HOUR);
         SET fechaActual = date_add(fechaActual, INTERVAL minutosInicio MINUTE);
         WHILE i <= maximoRegistros DO
            call debug_msg(TRUE, (select concat_ws('','Registro: ', fechaActual)));
            SET i = i + 1;
            SET fechaInicial = fechaActual;
            SET fechaActual = date_add(fechaActual, INTERVAL minutosPorRegistro MINUTE);
            SET fechaFinal = fechaActual;
            VALUES(pEmpresa, salaId, fechaInicial, fechaFinal, estado, now(), 0, now(), 0);
         END WHILE;
         SET fechaActual = date_add(fechaActual, INTERVAL 1 DAY);
      END WHILE;
      IF finDeCiclo = 1 THEN
         LEAVE ciclo;
      END IF;
   END LOOP ciclo;
   CLOSE crSalas;
END */$$
DELIMITER ;

